function dishCard(d,v){const e=dishEvaluation(d,v);return '<article class="card pr-dish"><div class="pr-eyebrow">'+esc(d.brand.toUpperCase()+' · '+d.kind)+'</div><h2>'+esc(d.name)+'</h2>'+badge(dishLabels[e.outcome],e.outcome==='conflict'?'pr-concern':'')+(d.components?'<p>'+esc(d.components.join(' · '))+'</p>':'')+'<p>'+esc(d.order_notes)+'</p>'+(d.source_limits?note(d.source_limits):'')+(d.concern_details?'<div class="pr-concerns"><strong>What to ask about</strong><ul>'+Object.entries(d.concern_details).map(([need,reason])=>'<li>'+esc(need)+': '+esc(reason)+'</li>').join('')+'</ul></div>':'')+note('Allergen evidence applies to the whole listed order. The exact sauce or ingredient responsible may not be identified in the source.')+'<details><summary>Why this result?</summary>'+e.rows.map(r=>'<div class="pr-evidence"><strong>'+esc(r.need)+'</strong>'+badge({supported:'Published preference',confirm:'Confirm preparation',conflict:'Reported conflict',unknown:'Unknown'}[r.status])+'<p>'+esc(r.reason)+'</p></div>').join('')+(!e.rows.length?note('Select your needs to compare this dish.'): '')+'</details>'+note(d.scope+' · Checked '+d.checked_on)+'<a class="linkbtn" href="'+safeUrl(d.source_url)+(d.source_page?'#page='+d.source_page:'')+'" target="_blank" rel="noopener noreferrer">Dish evidence ↗</a></article>';}
function user(){try{return typeof currentUser!=='undefined'?currentUser:null;}catch(_){return null;}}
function activeNeeds(){return [...new Set([...state.needs,...(state.groupOn?state.group:[])])];}
function button(label,act,value='',cls='secondary'){return '<button type="button" class="'+cls+'" data-pro-action="'+act+'" data-value="'+esc(value)+'">'+label+'</button>';}
function row(title,sub,act,value='',ico='arrow'){return '<button type="button" class="pr-row" data-pro-action="'+act+'" data-value="'+esc(value)+'"><span class="pr-row-text"><strong>'+esc(title)+'</strong>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</span>'+icon(ico)+'</button>';}
