 return heading(v.name,v.area+(v.distance==null?'':' · '+v.distance.toFixed(1)+' mi'))+needsSummary()+note('Potential options based on published menu information. Confirm every ingredient, modification and shared preparation with this location before ordering.')+
 '<h3>'+c.potential+' potential dish option'+(c.potential===1?'':'s')+'</h3>'+(options.length?options.map(x=>dishCard(x.dish,v)).join(''):badge('MORE INFORMATION NEEDED')+'<div class="card"><h3>No reviewed dish data for this restaurant yet.</h3>'+activeNeeds().map(n=>'<p><strong>'+esc(n)+'</strong> · Unknown</p>').join('')+'</div>')+
 (officialFor(v)?'<details class="pr-dining-manual"><summary>Official restaurant guidance & sources</summary>'+sourceCard(officialFor(v))+'</details>':'')+'<details class="pr-dining-manual"><summary>What should I ask the restaurant?</summary><div class="pr-group">'+['Confirm every ingredient, seasoning, sauce and substitution against your needs.','Ask about cooking oils, shared fryers, grills, utensils and preparation surfaces.','For halal or kosher, ask about current certification for this exact location and dish.'].map(t=>'<div class="pr-detail">'+esc(t)+'</div>').join('')+'</div></details>'+button('Back to restaurants','go','needs','primary')+(!v.lookup?button('View restaurant','openRestaurant',v.id,'secondary'):'');
