function filteredHappyDeals(){
 const coords=state.happyCenter||browseCoords(),today=new Date().toISOString().slice(0,10);
 return DEALS.filter(d=>d.active&&d.checked_on<=today&&d.expires_on>=today&&locationPoint(d))
 .map(d=>({...d,distance:coords?miles(coords.latitude,coords.longitude,+d.latitude,+d.longitude):null}))
 .filter(d=>state.happyBounds?withinHappyBounds(d,state.happyBounds):(d.distance===null||d.distance<=state.radius))
 .sort((a,b)=>(a.distance??Infinity)-(b.distance??Infinity));
}
function withinHappyBounds(d,b){return d.latitude>=b.south&&d.latitude<=b.north&&(b.west<=b.east?d.longitude>=b.west&&d.longitude<=b.east:d.longitude>=b.west||d.longitude<=b.east);}
function happyCards(){const deals=filteredHappyDeals();return deals.map((d,i)=>'<button type="button" id="prDeal-'+esc(d.id)+'" class="card pr-deal pr-deal-card" data-pro-action="happyDetail" data-value="'+esc(d.id)+'"><span class="pr-eyebrow">'+(i+1)+' · HAPPY HOUR'+(d.distance===null?'':' · '+d.distance.toFixed(1)+' MI')+'</span><strong class="pr-deal-name">'+esc(d.name)+'</strong><span class="pr-deal-summary">'+esc(d.offer)+'</span><small class="pr-deal-address">'+esc(d.address)+'</small><b class="pr-deal-cta">See times & specials ↗</b></button>').join('')+(!deals.length?'<div class="pr-empty"><h2>No sourced specials in this map area yet.</h2><p>Move or zoom out to explore. Our current coverage is limited; this does not mean nearby restaurants have no Happy Hour.</p>'+button('Show our covered area','coveredArea','','secondary')+'</div>':'');}
